1	import moment from 'moment';
2	import React, { useState, useEffect } from 'react';
3	import { ChevronDown, ChevronUp, ChevronRight, Menu } from 'lucide-react';
4	import Tooltip from '@hochhuth-consulting/hhhh-shared-ui/HHHH-UI/tooltips/Tooltip';
5	
6	
7	interface ResultTypeFilterProps {
8	    onFilterChange: (filters: string[]) => void;
9	    allFileTypeRefiners?: { RefinementValue: string }[];
10	    setResultTypesAllDoc: any;
11	    resultTypeAllDoc: any;
12	    clearFilterToggle: any;
13	    sites: any;
14	    selectedSiteTitles: any;
15	    setSelectedSiteTitles: any;
16	    resultTypeQueryPrepare: any;
17	    resultType: any;
18	    ContextValue: any;
19	    activeSites: any;
20	    activeSitesSelectedItems: any;
21	    setActiveSitesSelectedItems: (filters: string[]) => void;
22	    useForOMTTool: any;
23	}
24	
25	const ResultTypeFilter: React.FC<ResultTypeFilterProps> = ({
26	    useForOMTTool, activeSitesSelectedItems, setActiveSitesSelectedItems, activeSites,
27	    onFilterChange, resultType, allFileTypeRefiners, setResultTypesAllDoc, resultTypeAllDoc,
28	    clearFilterToggle, sites, selectedSiteTitles, setSelectedSiteTitles,
29	    resultTypeQueryPrepare, ContextValue
30	}) => {
31	    const [documentSelectAll, setDocumentSelectAll] = useState(false);
32	    const [documentTypes, setDocumentTypes] = useState<{ [key: string]: boolean }>({});
33	    const [standaloneSelectAll, setStandaloneSelectAll] = useState(false);
34	    const [standaloneTypes, setStandaloneTypes] = useState({ Task: false, Project: false, Portfolio: false });
35	
36	    const allSelectedSites = activeSitesSelectedItems.length > 0 &&
37	        Array.isArray(activeSites) &&
38	        activeSites.length > 0 &&
39	        activeSitesSelectedItems.length === activeSites.reduce((total: number, site: any) => total + (site.TaskLists?.length || 0), 0);
40	
41	    const handleDocumentSelectAll = (checked: boolean) => {
42	        setDocumentSelectAll(checked);
43	        const newDocumentTypes = Object.keys(documentTypes)?.reduce((acc, key) => {
44	            acc[key as keyof typeof documentTypes] = checked;
45	            return acc;
46	        }, {} as typeof documentTypes);
47	        setDocumentTypes(newDocumentTypes);
48	    };
49	
50	    const handleDocumentTypeChange = (type: keyof typeof documentTypes, checked: boolean) => {
51	        const newDocumentTypes = { ...documentTypes, [type]: checked };
52	        setDocumentTypes(newDocumentTypes);
53	        const allSelected = !Object.keys(newDocumentTypes).some(key => !newDocumentTypes[key as keyof typeof newDocumentTypes]);
54	        const noneSelected = Object.keys(newDocumentTypes).every(key => !newDocumentTypes[key as keyof typeof newDocumentTypes]);
55	        if (allSelected) setDocumentSelectAll(true);
56	        else if (noneSelected) setDocumentSelectAll(false);
57	    };
58	
59	    const handleStandaloneSelectAll = (checked: boolean) => {
60	        setStandaloneSelectAll(checked);
61	        let newDocumentTypes: any;
62	        if (ContextValue?.useForOnlyTasks === undefined || ContextValue?.useForOnlyTasks != true) {
63	            setDocumentSelectAll(checked);
64	            newDocumentTypes = Object.keys(documentTypes).reduce((acc, key) => {
65	                acc[key as keyof typeof documentTypes] = checked;
66	                return acc;
67	            }, {} as typeof documentTypes);
68	            setDocumentTypes(newDocumentTypes);
69	        }
70	        const newStandaloneTypes = Object.keys(standaloneTypes).reduce((acc, key) => {
71	            acc[key as keyof typeof standaloneTypes] = checked;
72	            return acc;
73	        }, {} as typeof standaloneTypes);
74	        setStandaloneTypes(newStandaloneTypes);
75	    };
76	
77	    const handleStandaloneTypeChange = (type: keyof typeof standaloneTypes, checked: boolean) => {
78	        const newStandaloneTypes = { ...standaloneTypes, [type]: checked };
79	        setStandaloneTypes(newStandaloneTypes);
80	        const allSelected = Object.keys(newStandaloneTypes).every(key => newStandaloneTypes[key as keyof typeof newStandaloneTypes]);
81	        const noneSelected = Object.keys(newStandaloneTypes).every(key => !newStandaloneTypes[key as keyof typeof newStandaloneTypes]);
82	        if (allSelected) setStandaloneSelectAll(true);
83	        else if (noneSelected) setStandaloneSelectAll(false);
84	    };
85	
86	    useEffect(() => {
87	        const selectedFilters: string[] = [];
88	        if (ContextValue?.useForOnlyTasks === undefined || ContextValue?.useForOnlyTasks != true) {
89	            if (documentSelectAll) selectedFilters.push('Document');
90	            Object.keys(documentTypes)?.forEach(key => { if (documentTypes[key as keyof typeof documentTypes]) selectedFilters.push(key); });
91	        }
92	        Object.keys(standaloneTypes)?.forEach(key => { if (standaloneTypes[key as keyof typeof standaloneTypes]) selectedFilters.push(key); });
93	        let documentFileType = selectedFilters?.filter((e: any) => e !== 'Task' && e !== 'Portfolio' && e !== 'Project');
94	        if (documentFileType?.length > 0) setResultTypesAllDoc(false);
95	        onFilterChange(selectedFilters);
96	        resultType.current = selectedFilters;
97	    }, [documentTypes, standaloneTypes, onFilterChange, setResultTypesAllDoc]);
98	
99	    useEffect(() => {
100	        if (allFileTypeRefiners && allFileTypeRefiners?.length > 0) {
101	            setDocumentSelectAll(false);
102	            const initialState: { [key: string]: boolean } = {};
103	            allFileTypeRefiners?.forEach((item: any) => {
104	                if (resultTypeQueryPrepare?.length > 0 && resultTypeQueryPrepare?.includes(item.RefinementValue)) {
105	                    resultTypeQueryPrepare?.forEach((type: any) => {
106	                        if (item.RefinementValue.toLowerCase() === type.toLowerCase()) initialState[item.RefinementValue] = true;
107	                        else initialState[item.RefinementValue] = false;
108	                    });
109	                } else {
110	                    initialState[item.RefinementValue] = false;
111	                }
112	            });
113	            setDocumentTypes(initialState);
114	        } else {
115	            setDocumentSelectAll(false);
116	            setDocumentTypes({});
117	        }
118	    }, [allFileTypeRefiners]);
119	
120	    useEffect(() => {
121	        if (clearFilterToggle) {
122	            setDocumentSelectAll(false);
123	            const initialState: { [key: string]: boolean } = {};
124	            allFileTypeRefiners?.forEach((item: any) => { initialState[item.RefinementValue] = false; });
125	            setDocumentTypes(initialState);
126	            setStandaloneSelectAll(false);
127	            setStandaloneTypes({ Task: false, Project: false, Portfolio: false });
128	            setResultTypesAllDoc(false);
129	            onFilterChange([]);
130	            resultType.current = [];
131	            setSelectedSiteTitles([]);
132	        }
133	    }, [clearFilterToggle]);
134	
135	    const handleTaskListSelect = (siteData: any, taskList: any) => {
136	        const itemToAdd = {
137	            siteTitle: siteData.Site.Title,
138	            siteUrl: siteData.Site.Url,
139	            siteId: siteData.Site.SiteId,
140	            webId: siteData.Site.WebId,
141	            taskListTitle: taskList.Title,
142	            taskListId: taskList.Id,
143	            taskListUrl: taskList.Url,
144	            coverImage: taskList.Item_x005F_x0020_Cover
145	        };
146	        const existsIndex = activeSitesSelectedItems?.findIndex((item: any) => item.taskListId === taskList.Id);
147	        let newSelectedItems: any[] = [];
148	        if (existsIndex >= 0) {
149	            newSelectedItems = activeSitesSelectedItems?.filter((_: any, index: any) => index !== existsIndex);
150	        } else {
151	            newSelectedItems = [...activeSitesSelectedItems, itemToAdd];
152	        }
153	        setActiveSitesSelectedItems(newSelectedItems);
154	        const siteUrl = siteData?.Site?.Url;
155	        const siteTaskLists = siteData?.TaskLists || [];
156	        const allListsOfSiteSelected = siteTaskLists.length > 0 && siteTaskLists.every((tl: any) => newSelectedItems.some((item: any) => item.taskListId === tl.Id));
157	        if (allListsOfSiteSelected) {
158	            if (!selectedSiteTitles?.includes(siteUrl)) setSelectedSiteTitles([...selectedSiteTitles, siteUrl]);
159	        } else {
160	            if (selectedSiteTitles?.includes(siteUrl)) setSelectedSiteTitles(selectedSiteTitles.filter((t: any) => t !== siteUrl));
161	        }
162	    };
163	
164	    const getCoverImageUrl = (taskList: any): string | null => {
165	        if (!taskList) return null;
166	        const cover = taskList?.Item_x005F_x0020_Cover || taskList?.Item_x0020_Cover || taskList?.coverImage || taskList?.ItemCoverURL;
167	        if (!cover) return null;
168	
169	        let rawUrl: string | null = null;
170	        if (typeof cover === 'object') {
171	            rawUrl = cover?.Url || cover?.url || cover?.URI || null;
172	        } else if (typeof cover === 'string') {
173	            const trimmed = cover.trim();
174	            if (trimmed.startsWith('{')) {
175	                try {
176	                    const parsed = JSON.parse(trimmed);
177	                    rawUrl = parsed?.Url || parsed?.url || null;
178	                } catch (e) {
179	                    rawUrl = null;
180	                }
181	            } else {
182	                rawUrl = trimmed;
183	            }
184	        }
185	
186	        if (!rawUrl) return null;
187	
188	        if (rawUrl.startsWith('https://') || rawUrl.startsWith('http://')) {
189	            return rawUrl;
190	        }
191	        if (rawUrl.startsWith('//')) {
192	            return `https:${rawUrl}`;
193	        }
194	        if (rawUrl.startsWith('/')) {
195	            const origin = ContextValue?.siteUrl ? new URL(ContextValue.siteUrl).origin : (typeof window !== 'undefined' ? window.location.origin : 'https://hhhhteams.sharepoint.com');
196	            return `${origin}${rawUrl}`;
197	        }
198	        return `https://${rawUrl}`;
199	    };
200	
201	    const isTaskListSelected = (taskListId: any) => activeSitesSelectedItems?.some((item: any) => item.taskListId === taskListId);
202	
203	    const getInitials = (title: any) => title.split(' ').map((word: any) => word[0]).join('').substring(0, 2).toUpperCase();
204	
205	    const getRandomColor = (id: any) => {
206	        const colors = ['#6f42c1', '#dc3545', '#fd7e14', '#ffc107', '#28a745', '#20c997', '#17a2b8', '#007bff', '#e83e8c', '#6c757d'];
207	        const index = (id || '').split('').reduce((acc: any, char: any) => acc + char.charCodeAt(0), 0) % colors.length;
208	        return colors[index];
209	    };
210	
211	    const handleSelectAllSites = (e: any) => {
212	        if (e.target.checked) {
213	            const allTaskLists = activeSites.flatMap((siteData: any) =>
214	                (siteData?.TaskLists || []).map((taskList: any) => ({
215	                    siteTitle: siteData.Site.Title, siteUrl: siteData.Site.Url, siteId: siteData.Site.SiteId,
216	                    webId: siteData.Site.WebId, taskListTitle: taskList.Title, taskListId: taskList.Id, taskListUrl: taskList.Url,
217	                    coverImage: taskList.Item_x005F_x0020_Cover || taskList.Item_x0020_Cover || taskList.coverImage
218	                }))
219	            );
220	            setSelectedSiteTitles(activeSites.map((s: any) => s.Site.Url));
221	            setActiveSitesSelectedItems(allTaskLists);
222	        } else {
223	            setSelectedSiteTitles([]);
224	            setActiveSitesSelectedItems([]);
225	        }
226	    };
227	
228	    const handleIndividualSitesChange = (siteUrl: any, checked: any, siteData: any) => {
229	        if (checked) {
230	            const taskLists = (siteData?.TaskLists || []).map((taskList: any) => ({
231	                siteTitle: siteData.Site.Title, siteUrl, siteId: siteData.Site.SiteId, webId: siteData.Site.WebId,
232	                taskListTitle: taskList.Title, taskListId: taskList.Id, taskListUrl: taskList.Url, coverImage: taskList.Item_x005F_x0020_Cover || taskList.Item_x0020_Cover || taskList.coverImage
233	            }));
234	            setActiveSitesSelectedItems(taskLists);
235	            setSelectedSiteTitles([siteUrl]);
236	        } else {
237	            const filtered = activeSitesSelectedItems.filter((m: any) => m.siteUrl !== siteUrl);
238	            setActiveSitesSelectedItems(filtered);
239	            setSelectedSiteTitles(selectedSiteTitles.filter((t: any) => t !== siteUrl));
240	        }
241	    };
242	
243	    useEffect(() => {
244	        console.log("[ResultTypeFilter] activeSites prop changed:", activeSites);
245	        if (activeSites && activeSites.length > 0 && activeSitesSelectedItems.length === 0 && useForOMTTool === true) {
246	            const allTaskLists = activeSites.flatMap((siteData: any) =>
247	                siteData?.TaskLists?.map((taskList: any) => ({
248	                    siteTitle: siteData.Site.Title, siteUrl: siteData.Site.Url, siteId: siteData.Site.SiteId, webId: siteData.Site.WebId,
249	                    taskListTitle: taskList.Title, taskListId: taskList.Id, taskListUrl: taskList.Url, coverImage: taskList.Item_x005F_x0020_Cover || taskList.Item_x0020_Cover || taskList.coverImage
250	                })) || []
251	            );
252	            setActiveSitesSelectedItems(allTaskLists);
253	            setSelectedSiteTitles(activeSites.map((siteData: any) => siteData.Site.Url));
254	        }
255	    }, [activeSites, useForOMTTool]);
256	
257	    const checkboxLabelCls = "flex items-center gap-2 cursor-pointer text-xs sm:text-sm text-slate-700 hover:text-slate-900 py-0.5 select-none transition-colors";
258	    const checkboxCls = "w-4 h-4 rounded border-slate-300 accent-[var(--SiteColor,#2F5596)] cursor-pointer shrink-0 transition-transform active:scale-90";
259	    const checkboxTextCls = "font-medium text-slate-700";
260	
261	    return (
262	        <div className="w-full space-y-3">
263	            {/* ── Sites Section ── */}
264	            <div className="mb-2">
265	                <details className="group">
266	                    <summary className="flex items-center justify-between cursor-pointer select-none py-3 px-4 rounded-lg bg-white border border-gray-200 text-slate-800 font-medium text-sm transition-all list-none shadow-sm mb-4">
267	                        <span className="flex items-center gap-3">
268	                            <ChevronRight className="w-5 h-5 text-[#2f5597] transition-transform group-open:rotate-90" />
269	                            <span className="text-[#2f5597] font-semibold text-base">Sites</span>
270	                        </span>
271	                        <div className="flex items-center gap-4">
272	                            {useForOMTTool === true && (
273	                                <span onClick={e => { e.stopPropagation(); e.nativeEvent.stopImmediatePropagation(); }} onMouseDown={e => { e.stopPropagation(); e.nativeEvent.stopImmediatePropagation(); }}>
274	                                    <Tooltip ComponentId={15962} />
275	                                </span>
276	                            )}
277	                        </div>
278	                    </summary>
279	
280	                    <label className={`${checkboxLabelCls} mt-2 px-2`}>
281	                        <input type="checkbox" className={checkboxCls} checked={allSelectedSites} onChange={handleSelectAllSites} />
282	                        <span className={checkboxTextCls}>Select All</span>
283	                    </label>
284	
285	                    <div className="mb-3 mt-1.5 space-y-3 px-2">
286	                        {activeSites?.map((siteData: any, siteIndex: any) => (
287	                            <div key={siteIndex} className="mb-3">
288	                                {/* Site Title with Checkbox */}
289	                                <div className="flex items-center mb-2 pb-1 border-b border-slate-100">
290	                                    <input
291	                                        type="checkbox"
292	                                        id={`site-${siteIndex}`}
293	                                        className={`${checkboxCls} mr-2`}
294	                                        checked={selectedSiteTitles?.includes(siteData?.Site?.Url)}
295	                                        onChange={e => handleIndividualSitesChange(siteData?.Site?.Url, e.target.checked, siteData)}
296	                                    />
297	                                    <label className="text-xs font-semibold text-slate-800 cursor-pointer hover:text-blue-600 transition-colors" htmlFor={`site-${siteIndex}`}>
298	                                        {siteData.Site.Title}
299	                                    </label>
300	                                </div>
301	                                {/* Task Lists — Avatar circles */}
302	                                <div className="flex flex-wrap gap-2 ml-3">
303	                                    {siteData?.TaskLists?.map((taskList: any, taskIndex: any) => {
304	                                        const coverUrl = getCoverImageUrl(taskList);
305	                                        const isSelected = isTaskListSelected(taskList.Id);
306	                                        return (
307	                                            <div
308	                                                key={taskIndex}
309	                                                onClick={() => handleTaskListSelect(siteData, taskList)}
310	                                                className="relative cursor-pointer"
311	                                                title={taskList.Title}
312	                                            >
313	                                                <div
314	                                                    className={`w-[26px] h-[26px] rounded-full flex items-center justify-center relative transition-all ${isSelected ? 'ring-2 ring-blue-600 scale-105 shadow-md' : 'ring-1 ring-slate-200 shadow-sm hover:scale-105 hover:ring-blue-300'}`}
315	                                                    style={{ backgroundColor: coverUrl ? 'transparent' : getRandomColor(taskList.Id) }}
316	                                                >
317	                                                    {coverUrl ? (
318	                                                        <img src={coverUrl} alt={taskList.Title} className="w-[22px] h-[22px] rounded-full object-cover" />
319	                                                    ) : (
320	                                                        <span className="text-white font-bold text-[9px]">{getInitials(taskList.Title)}</span>
321	                                                    )}
322	                                                </div>
323	                                                {isSelected && (
324	                                                    <div className="absolute -top-0.5 -right-0.5 w-3.5 h-3.5 bg-blue-600 rounded-full flex items-center justify-center border border-white shadow">
325	                                                        <i className="text-white text-[7px] not-italic font-bold">✓</i>
326	                                                    </div>
327	                                                )}
328	                                            </div>
329	                                        );
330	                                    })}
331	                                </div>
332	                            </div>
333	                        ))}
334	                    </div>
335	                </details>
336	            </div>
337	
338	            {/* ── Result Type Section ── */}
339	            {(useForOMTTool === undefined || useForOMTTool === null || useForOMTTool === false) && (
340	                <div className="mb-2">
341	                    <details className="group" open>
342	                        <summary className="flex items-center justify-between cursor-pointer select-none py-2 px-2.5 rounded-lg bg-slate-100/80 hover:bg-slate-200/60 text-slate-800 font-semibold text-xs uppercase tracking-wider transition-all list-none">
343	                            <span>Result type</span>
344	                        </summary>
345	
346	                        {/* Select All */}
347	                        <label className={`${checkboxLabelCls} mt-2 px-2`}>
348	                            <input
349	                                type="checkbox"
350	                                className={checkboxCls}
351	                                checked={standaloneSelectAll}
352	                                onChange={e => handleStandaloneSelectAll(e.target.checked)}
353	                            />
354	                            <span className={checkboxTextCls}>Select All</span>
355	                        </label>
356	
357	                        {/* Document types */}
358	                        {(ContextValue?.useForOnlyTasks === undefined || ContextValue?.useForOnlyTasks != true) && (
359	                            <div className="mt-1 px-2">
360	                                {allFileTypeRefiners?.length > 0 && Object.keys(documentTypes)?.length > 0 && (
361	                                    <div className="mb-2">
362	                                        <label className={`${checkboxLabelCls} font-semibold text-slate-800`}>
363	                                            <input type="checkbox" className={checkboxCls} checked={documentSelectAll} onChange={e => handleDocumentSelectAll(e.target.checked)} />
364	                                            <span className={checkboxTextCls}>DOCUMENT</span>
365	                                        </label>
366	                                        <div className="flex flex-col gap-1 border-l-2 border-slate-200 pl-3 ml-3 my-1.5">
367	                                            {Object.keys(documentTypes)?.map(type => (
368	                                                <label key={type} className={checkboxLabelCls}>
369	                                                    <input type="checkbox" className={checkboxCls} checked={documentTypes[type]} onChange={e => handleDocumentTypeChange(type, e.target.checked)} />
370	                                                    <span className={checkboxTextCls}>{type.toUpperCase()}</span>
371	                                                </label>
372	                                            ))}
373	                                        </div>
374	                                    </div>
375	                                )}
376	                                {allFileTypeRefiners?.length === 0 && (
377	                                    <div className="mb-2">
378	                                        <label className={`${checkboxLabelCls} font-semibold text-slate-800`}>
379	                                            <input type="checkbox" className={checkboxCls} checked={resultTypeAllDoc} onChange={e => setResultTypesAllDoc(e.target.checked)} />
380	                                            <span className={checkboxTextCls}>DOCUMENT</span>
381	                                        </label>
382	                                    </div>
383	                                )}
384	                            </div>
385	                        )}
386	
387	                        {/* Task / Portfolio / Project */}
388	                        <div className="flex flex-col gap-1 px-2 mt-1">
389	                            <label className={checkboxLabelCls}>
390	                                <input type="checkbox" className={checkboxCls} checked={standaloneTypes.Task} onChange={e => handleStandaloneTypeChange('Task', e.target.checked)} />
391	                                <span className={checkboxTextCls}>TASK (AWT)</span>
392	                            </label>
393	                            <label className={checkboxLabelCls}>
394	                                <input type="checkbox" className={checkboxCls} checked={standaloneTypes.Portfolio} onChange={e => handleStandaloneTypeChange('Portfolio', e.target.checked)} />
395	                                <span className={checkboxTextCls}>PORTFOLIO (CSF)</span>
396	                            </label>
397	                            <label className={checkboxLabelCls}>
398	                                <input type="checkbox" className={checkboxCls} checked={standaloneTypes.Project} onChange={e => handleStandaloneTypeChange('Project', e.target.checked)} />
399	                                <span className={checkboxTextCls}>PROJECT</span>
400	                            </label>
401	                        </div>
402	                    </details>
403	                </div>
404	            )}
405	        </div>
406	    );
407	};
408	
409	export default ResultTypeFilter;

