import moment from 'moment';
import React, { useState, useEffect } from 'react';
import { ChevronDown, ChevronUp, ChevronRight, Menu } from 'lucide-react';
import Tooltip from '@hochhuth-consulting/hhhh-shared-ui/HHHH-UI/tooltips/Tooltip';


interface ResultTypeFilterProps {
    onFilterChange: (filters: string[]) => void;
    allFileTypeRefiners?: { RefinementValue: string }[];
    setResultTypesAllDoc: any;
    resultTypeAllDoc: any;
    clearFilterToggle: any;
    sites: any;
    selectedSiteTitles: any;
    setSelectedSiteTitles: any;
    resultTypeQueryPrepare: any;
    resultType: any;
    ContextValue: any;
    activeSites: any;
    activeSitesSelectedItems: any;
    setActiveSitesSelectedItems: (filters: string[]) => void;
    useForOMTTool: any;
}

const ResultTypeFilter: React.FC<ResultTypeFilterProps> = ({
    useForOMTTool, activeSitesSelectedItems, setActiveSitesSelectedItems, activeSites,
    onFilterChange, resultType, allFileTypeRefiners, setResultTypesAllDoc, resultTypeAllDoc,
    clearFilterToggle, sites, selectedSiteTitles, setSelectedSiteTitles,
    resultTypeQueryPrepare, ContextValue
}) => {
    const [documentSelectAll, setDocumentSelectAll] = useState(false);
    const [documentTypes, setDocumentTypes] = useState<{ [key: string]: boolean }>({});
    const [standaloneSelectAll, setStandaloneSelectAll] = useState(false);
    const [standaloneTypes, setStandaloneTypes] = useState({ Task: false, Project: false, Portfolio: false });

    const allSelectedSites = activeSitesSelectedItems.length > 0 &&
        Array.isArray(activeSites) &&
        activeSites.length > 0 &&
        activeSitesSelectedItems.length === activeSites.reduce((total: number, site: any) => total + (site.TaskLists?.length || 0), 0);

    const handleDocumentSelectAll = (checked: boolean) => {
        setDocumentSelectAll(checked);
        const newDocumentTypes = Object.keys(documentTypes)?.reduce((acc, key) => {
            acc[key as keyof typeof documentTypes] = checked;
            return acc;
        }, {} as typeof documentTypes);
        setDocumentTypes(newDocumentTypes);
    };

    const handleDocumentTypeChange = (type: keyof typeof documentTypes, checked: boolean) => {
        const newDocumentTypes = { ...documentTypes, [type]: checked };
        setDocumentTypes(newDocumentTypes);
        const allSelected = !Object.keys(newDocumentTypes).some(key => !newDocumentTypes[key as keyof typeof newDocumentTypes]);
        const noneSelected = Object.keys(newDocumentTypes).every(key => !newDocumentTypes[key as keyof typeof newDocumentTypes]);
        if (allSelected) setDocumentSelectAll(true);
        else if (noneSelected) setDocumentSelectAll(false);
    };

    const handleStandaloneSelectAll = (checked: boolean) => {
        setStandaloneSelectAll(checked);
        let newDocumentTypes: any;
        if (ContextValue?.useForOnlyTasks === undefined || ContextValue?.useForOnlyTasks != true) {
            setDocumentSelectAll(checked);
            newDocumentTypes = Object.keys(documentTypes).reduce((acc, key) => {
                acc[key as keyof typeof documentTypes] = checked;
                return acc;
            }, {} as typeof documentTypes);
            setDocumentTypes(newDocumentTypes);
        }
        const newStandaloneTypes = Object.keys(standaloneTypes).reduce((acc, key) => {
            acc[key as keyof typeof standaloneTypes] = checked;
            return acc;
        }, {} as typeof standaloneTypes);
        setStandaloneTypes(newStandaloneTypes);
    };

    const handleStandaloneTypeChange = (type: keyof typeof standaloneTypes, checked: boolean) => {
        const newStandaloneTypes = { ...standaloneTypes, [type]: checked };
        setStandaloneTypes(newStandaloneTypes);
        const allSelected = Object.keys(newStandaloneTypes).every(key => newStandaloneTypes[key as keyof typeof newStandaloneTypes]);
        const noneSelected = Object.keys(newStandaloneTypes).every(key => !newStandaloneTypes[key as keyof typeof newStandaloneTypes]);
        if (allSelected) setStandaloneSelectAll(true);
        else if (noneSelected) setStandaloneSelectAll(false);
    };

    useEffect(() => {
        const selectedFilters: string[] = [];
        if (ContextValue?.useForOnlyTasks === undefined || ContextValue?.useForOnlyTasks != true) {
            if (documentSelectAll) selectedFilters.push('Document');
            Object.keys(documentTypes)?.forEach(key => { if (documentTypes[key as keyof typeof documentTypes]) selectedFilters.push(key); });
        }
        Object.keys(standaloneTypes)?.forEach(key => { if (standaloneTypes[key as keyof typeof standaloneTypes]) selectedFilters.push(key); });
        let documentFileType = selectedFilters?.filter((e: any) => e !== 'Task' && e !== 'Portfolio' && e !== 'Project');
        if (documentFileType?.length > 0) setResultTypesAllDoc(false);
        onFilterChange(selectedFilters);
        resultType.current = selectedFilters;
    }, [documentTypes, standaloneTypes, onFilterChange, setResultTypesAllDoc]);

    useEffect(() => {
        if (allFileTypeRefiners && allFileTypeRefiners?.length > 0) {
            setDocumentSelectAll(false);
            const initialState: { [key: string]: boolean } = {};
            allFileTypeRefiners?.forEach((item: any) => {
                if (resultTypeQueryPrepare?.length > 0 && resultTypeQueryPrepare?.includes(item.RefinementValue)) {
                    resultTypeQueryPrepare?.forEach((type: any) => {
                        if (item.RefinementValue.toLowerCase() === type.toLowerCase()) initialState[item.RefinementValue] = true;
                        else initialState[item.RefinementValue] = false;
                    });
                } else {
                    initialState[item.RefinementValue] = false;
                }
            });
            setDocumentTypes(initialState);
        } else {
            setDocumentSelectAll(false);
            setDocumentTypes({});
        }
    }, [allFileTypeRefiners]);

    useEffect(() => {
        if (clearFilterToggle) {
            setDocumentSelectAll(false);
            const initialState: { [key: string]: boolean } = {};
            allFileTypeRefiners?.forEach((item: any) => { initialState[item.RefinementValue] = false; });
            setDocumentTypes(initialState);
            setStandaloneSelectAll(false);
            setStandaloneTypes({ Task: false, Project: false, Portfolio: false });
            setResultTypesAllDoc(false);
            onFilterChange([]);
            resultType.current = [];
            setSelectedSiteTitles([]);
        }
    }, [clearFilterToggle]);

    const handleTaskListSelect = (siteData: any, taskList: any) => {
        const itemToAdd = {
            siteTitle: siteData.Site.Title,
            siteUrl: siteData.Site.Url,
            siteId: siteData.Site.SiteId,
            webId: siteData.Site.WebId,
            taskListTitle: taskList.Title,
            taskListId: taskList.Id,
            taskListUrl: taskList.Url,
            coverImage: taskList.Item_x005F_x0020_Cover
        };
        const existsIndex = activeSitesSelectedItems?.findIndex((item: any) => item.taskListId === taskList.Id);
        let newSelectedItems: any[] = [];
        if (existsIndex >= 0) {
            newSelectedItems = activeSitesSelectedItems?.filter((_: any, index: any) => index !== existsIndex);
        } else {
            newSelectedItems = [...activeSitesSelectedItems, itemToAdd];
        }
        setActiveSitesSelectedItems(newSelectedItems);
        const siteUrl = siteData?.Site?.Url;
        const siteTaskLists = siteData?.TaskLists || [];
        const allListsOfSiteSelected = siteTaskLists.length > 0 && siteTaskLists.every((tl: any) => newSelectedItems.some((item: any) => item.taskListId === tl.Id));
        if (allListsOfSiteSelected) {
            if (!selectedSiteTitles?.includes(siteUrl)) setSelectedSiteTitles([...selectedSiteTitles, siteUrl]);
        } else {
            if (selectedSiteTitles?.includes(siteUrl)) setSelectedSiteTitles(selectedSiteTitles.filter((t: any) => t !== siteUrl));
        }
    };

    const getCoverImageUrl = (taskList: any): string | null => {
        if (!taskList) return null;
        const cover = taskList?.Item_x005F_x0020_Cover || taskList?.Item_x0020_Cover || taskList?.coverImage || taskList?.ItemCoverURL;
        if (!cover) return null;

        let rawUrl: string | null = null;
        if (typeof cover === 'object') {
            rawUrl = cover?.Url || cover?.url || cover?.URI || null;
        } else if (typeof cover === 'string') {
            const trimmed = cover.trim();
            if (trimmed.startsWith('{')) {
                try {
                    const parsed = JSON.parse(trimmed);
                    rawUrl = parsed?.Url || parsed?.url || null;
                } catch (e) {
                    rawUrl = null;
                }
            } else {
                rawUrl = trimmed;
            }
        }

        if (!rawUrl) return null;

        if (rawUrl.startsWith('https://') || rawUrl.startsWith('http://')) {
            return rawUrl;
        }
        if (rawUrl.startsWith('//')) {
            return `https:${rawUrl}`;
        }
        if (rawUrl.startsWith('/')) {
            const origin = ContextValue?.siteUrl ? new URL(ContextValue.siteUrl).origin : (typeof window !== 'undefined' ? window.location.origin : 'https://hhhhteams.sharepoint.com');
            return `${origin}${rawUrl}`;
        }
        return `https://${rawUrl}`;
    };

    const isTaskListSelected = (taskListId: any) => activeSitesSelectedItems?.some((item: any) => item.taskListId === taskListId);

    const getInitials = (title: any) => title.split(' ').map((word: any) => word[0]).join('').substring(0, 2).toUpperCase();

    const getRandomColor = (id: any) => {
        const colors = ['#6f42c1', '#dc3545', '#fd7e14', '#ffc107', '#28a745', '#20c997', '#17a2b8', '#007bff', '#e83e8c', '#6c757d'];
        const index = (id || '').split('').reduce((acc: any, char: any) => acc + char.charCodeAt(0), 0) % colors.length;
        return colors[index];
    };

    const handleSelectAllSites = (e: any) => {
        if (e.target.checked) {
            const allTaskLists = activeSites.flatMap((siteData: any) =>
                (siteData?.TaskLists || []).map((taskList: any) => ({
                    siteTitle: siteData.Site.Title, siteUrl: siteData.Site.Url, siteId: siteData.Site.SiteId,
                    webId: siteData.Site.WebId, taskListTitle: taskList.Title, taskListId: taskList.Id, taskListUrl: taskList.Url,
                    coverImage: taskList.Item_x005F_x0020_Cover || taskList.Item_x0020_Cover || taskList.coverImage
                }))
            );
            setSelectedSiteTitles(activeSites.map((s: any) => s.Site.Url));
            setActiveSitesSelectedItems(allTaskLists);
        } else {
            setSelectedSiteTitles([]);
            setActiveSitesSelectedItems([]);
        }
    };

    const handleIndividualSitesChange = (siteUrl: any, checked: any, siteData: any) => {
        if (checked) {
            const taskLists = (siteData?.TaskLists || []).map((taskList: any) => ({
                siteTitle: siteData.Site.Title, siteUrl, siteId: siteData.Site.SiteId, webId: siteData.Site.WebId,
                taskListTitle: taskList.Title, taskListId: taskList.Id, taskListUrl: taskList.Url, coverImage: taskList.Item_x005F_x0020_Cover || taskList.Item_x0020_Cover || taskList.coverImage
            }));
            setActiveSitesSelectedItems(taskLists);
            setSelectedSiteTitles([siteUrl]);
        } else {
            const filtered = activeSitesSelectedItems.filter((m: any) => m.siteUrl !== siteUrl);
            setActiveSitesSelectedItems(filtered);
            setSelectedSiteTitles(selectedSiteTitles.filter((t: any) => t !== siteUrl));
        }
    };

    useEffect(() => {
        console.log("[ResultTypeFilter] activeSites prop changed:", activeSites);
        if (activeSites && activeSites.length > 0 && activeSitesSelectedItems.length === 0 && useForOMTTool === true) {
            const allTaskLists = activeSites.flatMap((siteData: any) =>
                siteData?.TaskLists?.map((taskList: any) => ({
                    siteTitle: siteData.Site.Title, siteUrl: siteData.Site.Url, siteId: siteData.Site.SiteId, webId: siteData.Site.WebId,
                    taskListTitle: taskList.Title, taskListId: taskList.Id, taskListUrl: taskList.Url, coverImage: taskList.Item_x005F_x0020_Cover || taskList.Item_x0020_Cover || taskList.coverImage
                })) || []
            );
            setActiveSitesSelectedItems(allTaskLists);
            setSelectedSiteTitles(activeSites.map((siteData: any) => siteData.Site.Url));
        }
    }, [activeSites, useForOMTTool]);

    const checkboxLabelCls = "flex items-center gap-2 cursor-pointer text-xs sm:text-sm text-slate-700 hover:text-slate-900 py-0.5 select-none transition-colors";
    const checkboxCls = "w-4 h-4 rounded border-slate-300 accent-[var(--SiteColor,#2F5596)] cursor-pointer shrink-0 transition-transform active:scale-90";
    const checkboxTextCls = "font-medium text-slate-700";

    return (
        <div className="w-full space-y-3">
            {/* ── Sites Section ── */}
            <div className="mb-2">
                <details className="group">
                    <summary className="flex items-center justify-between cursor-pointer select-none py-3 px-4 rounded-lg bg-white border border-gray-200 text-slate-800 font-medium text-sm transition-all list-none shadow-sm mb-4">
                        <span className="flex items-center gap-3">
                            <ChevronRight className="w-5 h-5 text-[#2f5597] transition-transform group-open:rotate-90" />
                            <span className="text-[#2f5597] font-semibold text-base">Sites</span>
                        </span>
                        <div className="flex items-center gap-4">
                            {useForOMTTool === true && (
                                <span onClick={e => { e.stopPropagation(); e.nativeEvent.stopImmediatePropagation(); }} onMouseDown={e => { e.stopPropagation(); e.nativeEvent.stopImmediatePropagation(); }}>
                                    <Tooltip ComponentId={15962} />
                                </span>
                            )}
                        </div>
                    </summary>

                    <label className={`${checkboxLabelCls} mt-2 px-2`}>
                        <input type="checkbox" className={checkboxCls} checked={allSelectedSites} onChange={handleSelectAllSites} />
                        <span className={checkboxTextCls}>Select All</span>
                    </label>

                    <div className="mb-3 mt-1.5 space-y-3 px-2">
                        {activeSites?.map((siteData: any, siteIndex: any) => (
                            <div key={siteIndex} className="mb-3">
                                {/* Site Title with Checkbox */}
                                <div className="flex items-center mb-2 pb-1 border-b border-slate-100">
                                    <input
                                        type="checkbox"
                                        id={`site-${siteIndex}`}
                                        className={`${checkboxCls} mr-2`}
                                        checked={selectedSiteTitles?.includes(siteData?.Site?.Url)}
                                        onChange={e => handleIndividualSitesChange(siteData?.Site?.Url, e.target.checked, siteData)}
                                    />
                                    <label className="text-xs font-semibold text-slate-800 cursor-pointer hover:text-blue-600 transition-colors" htmlFor={`site-${siteIndex}`}>
                                        {siteData.Site.Title}
                                    </label>
                                </div>
                                {/* Task Lists — Avatar circles */}
                                <div className="flex flex-wrap gap-2 ml-3">
                                    {siteData?.TaskLists?.map((taskList: any, taskIndex: any) => {
                                        const coverUrl = getCoverImageUrl(taskList);
                                        const isSelected = isTaskListSelected(taskList.Id);
                                        return (
                                            <div
                                                key={taskIndex}
                                                onClick={() => handleTaskListSelect(siteData, taskList)}
                                                className="relative cursor-pointer"
                                                title={taskList.Title}
                                            >
                                                <div
                                                    className={`w-[26px] h-[26px] rounded-full flex items-center justify-center relative transition-all ${isSelected ? 'ring-2 ring-blue-600 scale-105 shadow-md' : 'ring-1 ring-slate-200 shadow-sm hover:scale-105 hover:ring-blue-300'}`}
                                                    style={{ backgroundColor: coverUrl ? 'transparent' : getRandomColor(taskList.Id) }}
                                                >
                                                    {coverUrl ? (
                                                        <img src={coverUrl} alt={taskList.Title} className="w-[22px] h-[22px] rounded-full object-cover" />
                                                    ) : (
                                                        <span className="text-white font-bold text-[9px]">{getInitials(taskList.Title)}</span>
                                                    )}
                                                </div>
                                                {isSelected && (
                                                    <div className="absolute -top-0.5 -right-0.5 w-3.5 h-3.5 bg-blue-600 rounded-full flex items-center justify-center border border-white shadow">
                                                        <i className="text-white text-[7px] not-italic font-bold">✓</i>
                                                    </div>
                                                )}
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        ))}
                    </div>
                </details>
            </div>

            {/* ── Result Type Section ── */}
            {(useForOMTTool === undefined || useForOMTTool === null || useForOMTTool === false) && (
                <div className="mb-2">
                    <details className="group" open>
                        <summary className="flex items-center justify-between cursor-pointer select-none py-2 px-2.5 rounded-lg bg-slate-100/80 hover:bg-slate-200/60 text-slate-800 font-semibold text-xs uppercase tracking-wider transition-all list-none">
                            <span>Result type</span>
                        </summary>

                        {/* Select All */}
                        <label className={`${checkboxLabelCls} mt-2 px-2`}>
                            <input
                                type="checkbox"
                                className={checkboxCls}
                                checked={standaloneSelectAll}
                                onChange={e => handleStandaloneSelectAll(e.target.checked)}
                            />
                            <span className={checkboxTextCls}>Select All</span>
                        </label>

                        {/* Document types */}
                        {(ContextValue?.useForOnlyTasks === undefined || ContextValue?.useForOnlyTasks != true) && (
                            <div className="mt-1 px-2">
                                {allFileTypeRefiners?.length > 0 && Object.keys(documentTypes)?.length > 0 && (
                                    <div className="mb-2">
                                        <label className={`${checkboxLabelCls} font-semibold text-slate-800`}>
                                            <input type="checkbox" className={checkboxCls} checked={documentSelectAll} onChange={e => handleDocumentSelectAll(e.target.checked)} />
                                            <span className={checkboxTextCls}>DOCUMENT</span>
                                        </label>
                                        <div className="flex flex-col gap-1 border-l-2 border-slate-200 pl-3 ml-3 my-1.5">
                                            {Object.keys(documentTypes)?.map(type => (
                                                <label key={type} className={checkboxLabelCls}>
                                                    <input type="checkbox" className={checkboxCls} checked={documentTypes[type]} onChange={e => handleDocumentTypeChange(type, e.target.checked)} />
                                                    <span className={checkboxTextCls}>{type.toUpperCase()}</span>
                                                </label>
                                            ))}
                                        </div>
                                    </div>
                                )}
                                {allFileTypeRefiners?.length === 0 && (
                                    <div className="mb-2">
                                        <label className={`${checkboxLabelCls} font-semibold text-slate-800`}>
                                            <input type="checkbox" className={checkboxCls} checked={resultTypeAllDoc} onChange={e => setResultTypesAllDoc(e.target.checked)} />
                                            <span className={checkboxTextCls}>DOCUMENT</span>
                                        </label>
                                    </div>
                                )}
                            </div>
                        )}

                        {/* Task / Portfolio / Project */}
                        <div className="flex flex-col gap-1 px-2 mt-1">
                            <label className={checkboxLabelCls}>
                                <input type="checkbox" className={checkboxCls} checked={standaloneTypes.Task} onChange={e => handleStandaloneTypeChange('Task', e.target.checked)} />
                                <span className={checkboxTextCls}>TASK (AWT)</span>
                            </label>
                            <label className={checkboxLabelCls}>
                                <input type="checkbox" className={checkboxCls} checked={standaloneTypes.Portfolio} onChange={e => handleStandaloneTypeChange('Portfolio', e.target.checked)} />
                                <span className={checkboxTextCls}>PORTFOLIO (CSF)</span>
                            </label>
                            <label className={checkboxLabelCls}>
                                <input type="checkbox" className={checkboxCls} checked={standaloneTypes.Project} onChange={e => handleStandaloneTypeChange('Project', e.target.checked)} />
                                <span className={checkboxTextCls}>PROJECT</span>
                            </label>
                        </div>
                    </details>
                </div>
            )}
        </div>
    );
};

export default ResultTypeFilter;

