1	import { spfi, SPFx as spSPFx } from "@pnp/sp";
2	import "@pnp/sp/webs";
3	import "@pnp/sp/lists";
4	import "@pnp/sp/search";
5	
6	const normalizeUrl = (url: any): string =>
7	    (url || "").toString().toLowerCase().replace(/\/+$/, "");
8	
9	/**
10	 * Build Sites filter UI from SmartMetadata (TaxType Sites / Sites Old).
11	 * Groups by Parent.Title (SP / IPPF / mbeon) — same shape as HHHHQA search path.
12	 */
13	export function buildActiveSitesFromMetadata(allRootMetaData: any[]): any[] {
14	    const siteItems = (allRootMetaData || []).filter((meta: any) => {
15	        if (!meta) return false;
16	        const tax = meta.TaxType;
17	        if (tax !== "Sites" && tax !== "Sites Old") return false;
18	        if (meta.IsVisible === false || meta.IsVisible === 0 || meta.IsVisible === "0") return false;
19	        return Boolean(meta.listId && meta.Title);
20	    });
21	
22	    const grouped: Record<string, any> = {};
23	    siteItems.forEach((meta: any) => {
24	        const groupTitle = meta?.Parent?.Title || meta?.siteName || meta?.Title || "Sites";
25	        const key = String(groupTitle).toLowerCase();
26	        const siteUrl = meta.originalSiteUrl || meta.siteUrl || "";
27	        if (!grouped[key]) {
28	            grouped[key] = {
29	                Site: {
30	                    Title: groupTitle,
31	                    Url: siteUrl,
32	                    SiteId: meta.SiteId || "",
33	                    WebId: meta.WebId || ""
34	                },
35	                TaskLists: [] as any[]
36	            };
37	        } else if (siteUrl && !grouped[key].Site.Url) {
38	            grouped[key].Site.Url = siteUrl;
39	        }
40	
41	        const already = grouped[key].TaskLists.some(
42	            (t: any) =>
43	                (t.Id && meta.listId && t.Id.toLowerCase() === meta.listId.toLowerCase()) ||
44	                (t.Title && meta.Title && t.Title.toLowerCase() === meta.Title.toLowerCase())
45	        );
46	        if (already) return;
47	
48	        const coverObj =
49	            meta?.Item_x005F_x0020_Cover ||
50	            meta?.Item_x0020_Cover ||
51	            meta?.coverImage ||
52	            null;
53	
54	        grouped[key].TaskLists.push({
55	            Title: meta.Title,
56	            Id: meta.listId,
57	            Url: siteUrl
58	                ? `${siteUrl.replace(/\/+$/, "")}/Lists/${encodeURIComponent(meta.Title)}`
59	                : "",
60	            Item_x005F_x0020_Cover: coverObj,
61	            Item_x0020_Cover: coverObj,
62	            coverImage: coverObj
63	        });
64	    });
65	
66	    return Object.keys(grouped)
67	        .map((k) => grouped[k])
68	        .filter((g) => g.TaskLists?.length > 0);
69	}
70	
71	async function getFilteredTaskLists(activeSites: any, allRootMetaData: any) {
72	    const result: any = [];
73	    activeSites?.forEach((siteObj: any) => {
74	        const siteUrlNorm = normalizeUrl(siteObj.Site?.Url);
75	        const matchingRootItems = (allRootMetaData || []).filter((meta: any) => {
76	            if (!meta) return false;
77	            const metaUrlNorm = normalizeUrl(meta.siteUrl || meta.originalSiteUrl);
78	            return Boolean(metaUrlNorm && siteUrlNorm && metaUrlNorm === siteUrlNorm);
79	        });
80	
81	        if (!matchingRootItems.length) return;
82	
83	        const matchedTaskLists: any = [];
84	        siteObj?.TaskLists?.forEach((taskList: any) => {
85	            const matchedMeta = matchingRootItems.find((meta: any) => {
86	                if (meta.listId && taskList.Id && meta.listId.toLowerCase() === String(taskList.Id).toLowerCase()) {
87	                    return true;
88	                }
89	                return Boolean(
90	                    meta.Title &&
91	                    taskList.Title &&
92	                    meta.Title.toLowerCase() === String(taskList.Title).toLowerCase()
93	                );
94	            });
95	            if (matchedMeta) {
96	                const coverObj =
97	                    matchedMeta.Item_x005F_x0020_Cover ||
98	                    matchedMeta.Item_x0020_Cover ||
99	                    matchedMeta.coverImage ||
100	                    null;
101	                matchedTaskLists.push({
102	                    ...taskList,
103	                    Item_x005F_x0020_Cover: coverObj,
104	                    Item_x0020_Cover: coverObj,
105	                    coverImage: coverObj
106	                });
107	            }
108	        });
109	
110	        if (matchedTaskLists.length > 0) {
111	            result.push({
112	                Site: siteObj.Site,
113	                TaskLists: matchedTaskLists
114	            });
115	        }
116	    });
117	    return result;
118	}
119	
120	export async function getSubsitesForRoot({ spContext, AllRootMetaData }: any) {
121	    if (!spContext) {
122	        console.error("[FetchDynamicActiveSites] Missing SPFx context");
123	        return buildActiveSitesFromMetadata(AllRootMetaData);
124	    }
125	
126	    const sp = spfi().using(spSPFx(spContext));
127	    const rawUrl =
128	        spContext?.pageContext?.web?.absoluteUrl ||
129	        (typeof window !== "undefined" ? window.location.href : "");
130	    const rootUrl = rawUrl
131	        ? rawUrl.match(/^(https?:\/\/[^\/]+\/sites\/[^\/\?#]+)/i)?.[1] ||
132	        rawUrl.replace(/\/+$/, "")
133	        : "https://hhhhteams.sharepoint.com/sites/HHHH";
134	
135	    // Step 1: Get webs under the site collection (HHHHQA parity)
136	    let subsites: any[] = [];
137	    try {
138	        const subsiteResults = await sp.search({
139	            Querytext: `Path:${rootUrl}* contentclass:STS_Web`,
140	            RowLimit: 100,
141	            SelectProperties: ["Title", "Path", "SiteId", "WebId"]
142	        });
143	        subsites = (subsiteResults?.PrimarySearchResults || []).map((r: any) => ({
144	            Title: r.Title,
145	            Url: r.Path,
146	            SiteId: r.SiteId,
147	            WebId: r.WebId
148	        }));
149	    } catch (err) {
150	        console.error("[FetchDynamicActiveSites] Error searching subsites:", err);
151	    }
152	
153	    // Also include unique siteUrls from Sites metadata (covers webs search may miss)
154	    const urlSet = new Set(subsites.map((s) => normalizeUrl(s.Url)));
155	    (AllRootMetaData || []).forEach((meta: any) => {
156	        if (
157	            (meta?.TaxType === "Sites" || meta?.TaxType === "Sites Old") &&
158	            meta?.siteUrl &&
159	            !urlSet.has(normalizeUrl(meta.siteUrl))
160	        ) {
161	            urlSet.add(normalizeUrl(meta.siteUrl));
162	            subsites.push({
163	                Title: meta?.Parent?.Title || meta?.siteName || meta?.Title,
164	                Url: meta.siteUrl,
165	                SiteId: "",
166	                WebId: ""
167	            });
168	        }
169	    });
170	
171	    // Step 2: For each web, fetch Task lists (BaseTemplate 171 — HHHHQA parity)
172	    const siteTasks = await Promise.all(
173	        subsites.map(async (site) => {
174	            try {
175	                const siteSp = spfi(site.Url).using(spSPFx(spContext));
176	                const lists = await siteSp.web.lists();
177	                const taskLists = lists?.filter((l: any) => l.BaseTemplate === 171);
178	                const excludedTitles: string[] = [
179	                    "Offshore Tasks",
180	                    "Master Tasks",
181	                    "DRR",
182	                    "SDC Sites",
183	                    "QA",
184	                    "Foundation",
185	                    "Health",
186	                    "Gender",
187	                    "SP Online"
188	                ];
189	                const activeTaskList = taskLists?.filter(
190	                    (taskList: any) =>
191	                        taskList?.Title !== undefined && !excludedTitles.includes(taskList.Title)
192	                );
193	                return {
194	                    Site: site,
195	                    TaskLists: activeTaskList?.map((l: any) => ({
196	                        Title: l.Title,
197	                        Id: l.Id,
198	                        Url: `${site.Url}/Lists/${encodeURIComponent(l.Title)}`
199	                    }))
200	                };
201	            } catch (e) {
202	                console.log(`Error fetching lists for ${site.Url}`, e);
203	                return { Site: site, TaskLists: [] };
204	            }
205	        })
206	    );
207	
208	    const AllRootSites = (AllRootMetaData || []).filter(
209	        (root: any) => root?.TaxType === "Sites" || root?.TaxType === "Sites Old"
210	    );
211	    const activesitesTasks = siteTasks?.filter((e) => e.TaskLists?.length > 0);
212	    let activeTAsklist = await getFilteredTaskLists(activesitesTasks, AllRootSites);
213	
214	    // Prefer search+list path when it produced sites (HHHHQA behavior)
