import { Web } from "sp-pnp-js";
import * as globalCommon from "@hochhuth-consulting/hhhh-shared-ui/HHHH-SP-Code/services/globalCommon";

/**
 * Resolve SharePoint site URLs from SmartMetadata / RootDashboardConfig.
 * Handles absolute URLs, server-relative paths (/sites/...), and blank values
 * (falls back to the parent hub URL). Matches OOTBSearchOMT metadata loading.
 */
export function resolveAbsoluteSiteUrl(
    rawUrl: string | { Url?: string } | null | undefined,
    hubSiteUrl?: string
): string {
    const raw = String(
        typeof rawUrl === "object" && rawUrl !== null
            ? (rawUrl as { Url?: string }).Url ?? ""
            : rawUrl ?? ""
    ).trim();
    const hub = String(hubSiteUrl || "").replace(/\/+$/, "");
    if (!raw) return hub;
    if (/^https?:\/\//i.test(raw)) return raw.replace(/\/+$/, "");
    if (raw.startsWith("/")) {
        let origin = "";
        if (hub && /^https?:\/\//i.test(hub)) {
            try {
                origin = new URL(hub).origin;
            } catch {
                /* ignore */
            }
        }
        if (!origin && typeof window !== "undefined") {
            origin = window.location.origin;
        }
        return origin ? `${origin}${raw}`.replace(/\/+$/, "") : raw.replace(/\/+$/, "");
    }
    if (hub && /^https?:\/\//i.test(hub)) {
        return `${hub}/${raw}`.replace(/\/+$/, "");
    }
    return raw.replace(/\/+$/, "");
}

/** Apply hub URL + Configurations JSON — same enrichment as OOTBSearchOMT. */
export function enrichSitesMetadataRow(item: any, hub: any): any {
    const hubUrl = resolveAbsoluteSiteUrl(hub?.siteUrl);
    if (!item) return item;
    item.originalSiteUrl = item.siteUrl || hubUrl;
    item.siteUrl = resolveAbsoluteSiteUrl(item.siteUrl, hubUrl) || hubUrl;
    item.hubSiteUrl = hubUrl;
    if (
        item.Configurations &&
        (item.TaxType === "Sites" || item.TaxType === "Sites Old")
    ) {
        try {
            const configArr =
                typeof item.Configurations === "string"
                    ? globalCommon.parseJSON(item.Configurations)
                    : item.Configurations;
            if (Array.isArray(configArr) && configArr.length > 0) {
                const conf = configArr[0];
                item.listId = item.listId || conf.listId;
                item.siteName =
                    item.siteName || conf.siteName || conf.Title || item.Title;
                if (conf.siteUrl) {
                    item.originalSiteUrl = conf.siteUrl;
                    item.siteUrl = resolveAbsoluteSiteUrl(conf.siteUrl, hubUrl);
                }
                item.Item_x005F_x0020_Cover =
                    item.Item_x005F_x0020_Cover ||
                    conf.ImageUrl ||
                    conf.Item_x005F_x0020_Cover;
            }
        } catch (e) {
            console.error("[OMT] Error parsing Sites Configurations", e);
        }
    }
    return item;
}

export type LoadOmtHubMetadataOptions = {
    /** When set, only these TaxType values are requested from SharePoint. */
    taxTypes?: string[];
};

const DEFAULT_TAX_TYPES = [
    "Sites",
    "Sites Old",
    "timesheetListConfigrations",
];

const SITES_TAX_TYPES = ["Sites", "Sites Old"];

function buildTaxTypeFilter(taxTypes: string[]): string {
    return taxTypes.map((t) => `TaxType eq '${t}'`).join(" or ");
}

/**
 * Load SmartMetadata from each unique hub (siteUrl + SmartMetadataListID).
 * Dedupes by url|listId — not by url alone — so hubs sharing a URL but
 * different list IDs are not silently skipped.
 */
export async function loadOmtHubSmartMetadata(
    rootSiteData: any[],
    options?: LoadOmtHubMetadataOptions
): Promise<any[]> {
    const taxTypes =
        options?.taxTypes?.length ? options.taxTypes : DEFAULT_TAX_TYPES;
    const taxFilter = buildTaxTypeFilter(taxTypes);

    const seenMetaLists = new Set<string>();
    const hubs = (rootSiteData || []).filter((site: any) => {
        const name = String(site?.siteName || site?.Title || "").toLowerCase();
        if (name === "ksl" || name === "smartmanagement") return false;
        const listId = site?.SmartMetadataListID || site?.metadataListId;
        const url = resolveAbsoluteSiteUrl(site?.siteUrl).toLowerCase();
        if (!listId || !url) return false;
        const key = `${url}|${listId}`;
        if (seenMetaLists.has(key)) return false;
        seenMetaLists.add(key);
        return true;
    });

    const sitesDataPromises = hubs.map(async (hub: any) => {
        const hubUrl = resolveAbsoluteSiteUrl(hub.siteUrl);
        if (!hubUrl) return [];
        const metaListId = hub?.SmartMetadataListID || hub?.metadataListId;
        try {
            const webSvc = new Web(hubUrl);
            const metaData: any[] = await webSvc.lists
                .getById(metaListId)
                .items.select(
                    "Id",
                    "Title",
                    "IsVisible",
                    "ParentID",
                    "SmartSuggestions",
                    "TaxType",
                    "Configurations",
                    "Item_x005F_x0020_Cover",
                    "listId",
                    "siteName",
                    "siteUrl",
                    "SortOrder",
                    "SmartFilters",
                    "Selectable",
                    "Color_x0020_Tag",
                    "Parent/Id",
                    "Parent/Title"
                )
                .expand("Parent")
                .filter(taxFilter)
                .top(4999)
                .get();
            return (metaData || []).map((row) =>
                enrichSitesMetadataRow(row, { ...hub, siteUrl: hubUrl })
            );
        } catch (error) {
            console.error(
                `[OMT] Failed loading SmartMetadata from ${hubUrl}:`,
                error
            );
            return [];
        }
    });

    const sitesArrays = await Promise.all(
        sitesDataPromises.map((p) => p.catch((): any[] => []))
    );
    return [].concat.apply([], sitesArrays);
}

/** Sites TaxType rows with resolved listId + absolute siteUrl for task loading. */
export async function loadOmtSitesTaskEntries(
    rootSiteData: any[]
): Promise<any[]> {
    const allMeta = await loadOmtHubSmartMetadata(rootSiteData, {
        taxTypes: SITES_TAX_TYPES,
    });
    return allMeta.filter(
        (item) =>
            (item?.TaxType === "Sites" || item?.TaxType === "Sites Old") &&
            item?.listId &&
            resolveAbsoluteSiteUrl(item.siteUrl, item.hubSiteUrl)
    );
}

