import * as React from "react";
import { Panel, PanelType } from "@fluentui/react";

const fields: string[] = [
    "Title",
    "Description",
    "Content",
    "Filename",
    "Author",
    "Editor",
    "Path",
    "ListName",
    "ContentType",
    "SiteName",
    "Tags",
];


const AdvanceSearchPopup = (props: any) => {
    // ✅ Dynamic initialization
    const [advanceSearchData, setAdvanceSearchData] = React.useState(() => {
        const initial: Record<string, boolean> = {};

        fields.forEach((field) => {
            // Use value from props if available, else default to false
            initial[field] = props?.advanceSearchData?.[field] || false;
        });

        return initial;
    });


    // ✅ Dynamic checkbox handler
    const onCheckboxChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, checked } = e.target;

        if (name === "selectAll") {
            // 🔹 Select or deselect all dynamically
            setAdvanceSearchData((prev) => {
                const updated: Record<string, boolean> = {};
                Object.keys(prev).forEach((key) => {
                    updated[key] = checked;
                });
                return updated;
            });
        } else {
            // 🔹 Update individual checkbox
            setAdvanceSearchData((prev) => ({
                ...prev,
                [name]: checked,
            }));
        }
    };

    // ✅ Close popup
    const dismissPanel = () => props?.setIsAdvanceSearchPopup(false);

    // ✅ Apply selected data
    const handleChangeData = () => {
        props?.setAdvanceSearchData(advanceSearchData);
        props?.setIsAdvanceSearchPopup(false);
    };


    // ✅ Header render
    const onRenderCustomHeader = () => {
        return (
            <div className="flex items-center px-4 pt-4 pb-2">
                <span className="text-[22px] font-medium text-[var(--SiteColor)]">HHHH Advanced SmartSearch</span>
            </div>
        );
    };

    // ✅ Ref for indeterminate visual state
    const selectAllRef = React.useRef<HTMLInputElement>(null);
    React.useEffect(() => {
        if (selectAllRef.current) {
            const values = Object.keys(advanceSearchData).map(k => advanceSearchData[k]);

            selectAllRef.current.indeterminate =
                values.some(Boolean) && !values.every(Boolean);
        }
    }, [advanceSearchData]);

    return (
        <div>
            <Panel
                className="overflow-x-visible"
                type={PanelType.custom}
                customWidth="370px"
                isOpen={props?.isOpen}
                onDismiss={dismissPanel}
                onRenderHeader={onRenderCustomHeader}
                isBlocking={false}
            >
                <div className="px-4 pt-2 pb-3">
                    <div className="w-full">
                        <div className="pt-1 pb-3">
                            <table className="w-full">
                                <tbody className="border-0">
                                    {/* ✅ Dynamic checkboxes */}
                                    {fields.map((field: string) => (
                                        <tr key={field}>
                                            <td style={{ width: "100%" }}>
                                                <label className="flex items-center gap-2 py-1 cursor-pointer text-sm text-gray-700 hover:text-gray-900">
                                                    <input
                                                        className="w-4 h-4 accent-[var(--SiteColor,#2F5596)] cursor-pointer"
                                                        id={field}
                                                        type="checkbox"
                                                        name={field}
                                                        checked={advanceSearchData[field] || false}
                                                        onChange={onCheckboxChange}
                                                    />
                                                    {field}
                                                </label>
                                            </td>
                                        </tr>
                                    ))}

                                    {/* ✅ "Select All" */}
                                    <tr>
                                        <td style={{ width: "100%" }}>
                                            <label className="flex items-center gap-2 py-1 cursor-pointer text-sm font-semibold text-gray-700 border-t border-gray-100 mt-1 pt-2">
                                                <input
                                                    ref={selectAllRef}
                                                    className="w-4 h-4 accent-[var(--SiteColor,#2F5596)] cursor-pointer"
                                                    type="checkbox"
                                                    name="selectAll"
                                                    checked={Object.keys(advanceSearchData).map(k => advanceSearchData[k]).every(Boolean)}
                                                    onChange={onCheckboxChange}
                                                />
                                                All Content
                                            </label>
                                        </td>
                                    </tr>
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
                <footer data-modal-actions="" className="absolute bottom-0 left-0 right-0 bg-white border-t border-gray-200 px-4 py-3 flex justify-end gap-2">
                    <button type="button" className="rounded bg-[var(--SiteColor)] px-4 py-2 text-sm font-semibold text-white hover:opacity-90 transition-colors border-none" onClick={handleChangeData}>
                        Apply
                    </button>
                    <button type="button" className="rounded border border-gray-300 px-4 py-2 text-sm text-gray-700 hover:bg-gray-50 transition-colors bg-white" onClick={dismissPanel}>
                        Cancel
                    </button>
                </footer>
            </Panel>
        </div>
    );
};
export default AdvanceSearchPopup;

